def investigar_verbo(palavra, frase):
    if not flexiona_em_pessoa_e_tempo(palavra, frase):
        return 'investigar outra classe (ex.: substantivo homônimo)'
    analise = {'classe': 'verbo'}
    aux = auxiliar_anterior(palavra, frase)
    if aux:
        analise['locucao_verbal'] = f'{aux} {palavra}'
    analise['transitividade'] = transitividade_no_contexto(palavra, frase)
    return analise

