def investigar_adverbio(palavra, frase):
    alvo = termo_modificado(palavra, frase)
    if concorda_com_nome(palavra, frase):
        return 'investigar pronome indefinido ou adjetivo'
    if eh_verbo(alvo):
        return f'advérbio de {circunstancia(palavra, frase)} modificando {alvo}'
    if eh_adjetivo(alvo) or eh_adverbio(alvo):
        return f'advérbio (intensidade) modificando {alvo}'
    return 'analisar o contexto completo'

def investigar_locucao_adverbial(expr, frase):
    alvo = termo_modificado(expr, frase)
    if eh_substantivo(alvo):
        return 'investigar locução adjetiva'
    if eh_verbo(alvo):
        if verbo_exige_preposicao(alvo, expr):
            return 'complemento verbal (regência)'
        return f'locução adverbial de {circunstancia(expr, frase)}'
    return 'analisar o contexto completo'
